import numpy as np
from PIL import Image

# Create tmp directory if it doesn't exist
os.makedirs('./tmp/', exist_ok=True)

# Create an image with features illustrating lossy compression
# Using a pattern that would show compression artifacts well
width, height = 400, 300

# Create a gradient image with fine details that demonstrate lossy compression
# We'll create a pattern with alternating light/dark areas and fine details
image_data = np.zeros((height, width, 3), dtype=np.uint8)

# Create horizontal gradient background
for y in range(height):
    for x in range(width):
        # Gradient from black to white
        val = int((x / width) * 255)
        image_data[y, x] = [val, val, val]

# Add some high-contrast patterns that would show compression artifacts
# Add fine stripes
for y in range(0, height, 2):
    for x in range(0, width, 4):
        if (y // 2 + x // 4) % 2 == 0:
            image_data[y:y+2, x:x+4] = [255, 255, 255]

# Add some text indicating the concept
text_y = height // 2 - 15
for i, char in enumerate("JPEG: LOSSY COMPRESSION"):
    # Simple text rendering
    for dy in range(12):
        for dx in range(8):
            if i * 20 + dx < width and dy < height:
                # Create simple character pattern
                if char == ' ':
                    continue
                # Simple representation of letters
                if char in 'LOSEY':
                    if dx < 6 and dy < 10:
                        image_data[text_y + dy, i * 20 + dx] = [0, 0, 0]
                elif char in 'COMPR':
                    if dx < 6 and dy < 10:
                        image_data[text_y + dy, i * 20 + dx] = [0, 0, 0]
                elif char in 'SSIN':
                    if dx < 6 and dy < 10:
                        image_data[text_y + dy, i * 20 + dx] = [0, 0, 0]

# Save as JPEG with lossy compression (default quality)
jpg_path = "./tmp/jpeg_lossy_compression.jpg"
img = Image.fromarray(image_data)
img.save(jpg_path, 'JPEG', quality=85)  # quality parameter controls the amount of lossy compression

print(f"Saved JPEG file with lossy compression to {jpg_path}")
