            },
            "xmpRights:UsageTerms": {
                "@lang": "x-default",
                "xmpRights:Website": "https://example.com"
            }
        }
    }

    # Convert the dictionary to an XML-like string
    def dict_to_xml(data, indent=0):
        lines = []
        for key, value in data.items():
            if key.startswith('@'):
                continue  # Skip attributes for simplicity in this example
            if isinstance(value, dict):
                if key in ["xmpMM:History", "xmpRights:UsageTerms"]:
                    lines.append(f"{'  ' * indent}<{key}>")
                    lines.append(dict_to_xml(value, indent + 1))
                    lines.append(f"{'  ' * indent}</{key}>")
                elif key == "xmpMM:Versions":
                    lines.append(f"{'  ' * indent}<{key}>")
                    for item in value:
                        lines.append(f"{'  ' * indent}  <xmpMM:Version")
                        for attr, attr_value in item.items():
                            if attr.startswith('@'):
                                attr_name = attr[1:]
                                lines[-1] += f' {attr_name}="{attr_value}"'
                        lines[-1] += "/>"
                    lines.append(f"{'  ' * indent}</{key}>")
                else:
                    lines.append(f"{'  ' * indent}<{key}>")
                    lines.append(dict_to_xml(value, indent + 1))
                    lines.append(f"{'  ' * indent}</{key}>")
            elif isinstance(value, str):
                lines.append(f"{'  ' * indent}<{key}>{value}</{key}>")
            elif isinstance(value, list):
                for item in value:
                    lines.append(f"{'  ' * indent}<{key}>")
                    lines.append(dict_to_xml(item, indent + 1))
                    lines.append(f"{'  ' * indent}</{key}>")
        return "\n".join(lines)

