import os
from PIL import Image

os.makedirs('./tmp', exist_ok=True)

def create_lossless_tiff_with_metadata(filename: str, width: int = 100, height: int = 100, compression: str = 'deflate', color_space: str = 'RGB') -> None:
    """
    Creates a TIFF file with lossless compression, optional symbolic color space,
    and non-photometric metadata (color matrices and device-independent color info).

    Args:
        filename: Path to save the TIFF file.
        width: Width of the image.
        height: Height of the image.
        compression: Compression method ('deflate', 'lzw', 'packbits'). Default is 'deflate'.
        color_space: Color space mode ('RGB', 'L', 'LA', 'Lab', 'XYZ'). Default is 'RGB'.
                     'Lab' and 'XYZ' require the 'colorspace' plugin in Pillow to be installed.
    """
    # Wrap the entire image creation and processing in a try-except block
    try:
        img = Image.new(color_space, (width, height), color=None)
        pixels = img.load()

        # Populate image data based on color space
        if color_space == 'RGB':
            for i in range(width):
                for j in range(height):
                    pixels[i, j] = (i % 256, j % 256, (i + j) % 256)
        elif color_space == 'L':
            for i in range(width):
                for j in range(height):
                    pixels[i, j] = (i % 256,)
        elif color_space == 'LA':
            for i in range(width):
                for j in range(height):
                    pixels[i, j] = (i % 256, (i + j) % 256)
        elif color_space in ('Lab', 'XYZ'):
            if color_space == 'Lab':
                for i in range(width):
                    for j in range(height):
                        l_val = (i % 100)
                        a_val = (j % 256) - 128
                        b_val = ((i + j) % 256) - 128
                        pixels[i, j] = (l_val, a_val, b_val)
            elif color_space == 'XYZ':
                for i in range(width):
                    for j in range(height):
                        x_val = (i % 100)
                        y_val = (j % 100)
                        z_val = ((i + j) % 100)
                        pixels[i, j] = (x_val, y_val, z_val)

        # Save the image with non-photometric metadata
        img.save(
            filename,
            format='TIFF',
            compression=compression,
            photometric='opaque' if color_space in ('Lab', 'XYZ') else None,
            **({
                'nonphotometric': {
                    'type': 'color_map',
                    'data': {
                        'matrix': [[0.4124, 0.3576, 0.1805], [0.2126, 0.7152, 0.0722], [0.0193, 0.1192, 0.9505]],
                        'device_colors': [[255, 0, 0], [0, 255, 0], [0, 0, 255]]
                    }
                }
            }) if color_space in ('RGB', 'Lab', 'XYZ') else {}
        )
        print(f"Created lossless TIFF with {color_space} color space and non-photometric metadata: {filename}")

    except ValueError as e:
        # Specifically catch the "unrecognized image mode" error which often 
        # indicates the 'colorspace' plugin is missing for Lab/XYZ
        if "unrecognized image mode" in str(e) or "colorspace" in str(e):
            print(f"Error creating {filename} with {color_space} color space: {e}")
            print("Falling back to RGB due to missing plugin or unsupported mode.")
            create_lossless_tiff_with_metadata(filename, width, height, compression, 'RGB')
        else:
            raise

# Generate files for different modes to demonstrate
